#define MAX_ITERATIONS 100
#define BAILOUT_RADIUS 10.
#define AALIAS 2

// from shadertoy/csKcDm
const int NUM_COLORS = 16;
const vec3[] colors = vec3[](
    vec3( 66,  30,  15) / 255.,
    vec3( 25,   7,  26) / 255.,
    vec3(  9,   1,  47) / 255.,
    vec3(  4,   4,  73) / 255.,
    vec3(  0,   7, 100) / 255.,
