);

vec2 compmul(vec2 a, vec2 b) {
    return vec2(a.x*b.x-a.y*b.y, a.x*b.y+a.y*b.x);
}

vec2 compexp(vec2 z, float e) {
    float r = sqrt(dot(z, z));
    float th = atan(z.y,z.x);
    r = pow(r, e);
    th = th * e;
    return vec2(r * cos(th), r * sin(th));
}

// pos: for additional sampling if needed
// returns a smoothed iteration
float fractal(vec2 a, vec2 b, vec2 pos) {
    vec2 exponents = vec2(1., 3.);
    // outer max is not needed, only here for photosensitivity triggers
    float log_ = log(max(2., max(exponents.x, exponents.y)));

    for (int i = 0; i < MAX_ITERATIONS; i++) {
        vec2 coeff0 = vec2(.99 + .005 * cos(iTime), .01 + .005 * sin(iTime));
        vec2 coeff1 = vec2(1., 0.);
        vec2 c =
            compmul(coeff0, compexp(a, exponents.x)) +
            compmul(coeff1, compexp(b, exponents.y));

        a = b;
        b = c;
        if (dot(c, c) > BAILOUT_RADIUS * BAILOUT_RADIUS) {
            float log_zn = log(dot(c, c)) / 2.;
            float nu = log(log_zn / log_) / log_;
            return (float(i) + 1. - nu) / float(MAX_ITERATIONS);
        }
    }

    return 1.;
}

vec3 colorize(float it) {
    if (it == 1.)
        return vec3(0., 0., 0.);

    //return vec3(0.5) + vec3(0.5) * cos(6.28 * (3.14 * it + vec3(0.0, 0.1, 0.16)));
    float i = mod(it * float(MAX_ITERATIONS), float(NUM_COLORS));
    int i0 = int(floor(i));
    vec3 col0 = colors[i0];
    vec3 col1 = colors[(i0 + 1) % NUM_COLORS];
    return mix(col0, col1, fract(i));
}

vec4 aalias(vec2 fragCoord) {
    vec4 state = texelFetch(iChannel0, ivec2(0., 0.), 0);
    vec2 offset = state.xy;
    float zoom = state.z;

    vec3 col = vec3(0., 0., 0.);
    #ifdef AALIAS
    for (int dx = 0; dx < AALIAS; dx++)
    for (int dy = 0; dy < AALIAS; dy++) {
        vec2 add = vec2(float(dx)/float(AALIAS), float(dy)/float(AALIAS));
        vec2 uv = (fragCoord + add) / iResolution.xy;
    #else
        vec2 uv = fragCoord / iResolution.xy;
    #endif /* AALIAS */
        vec2 pos = (uv - vec2(.5, .5)) * 2.;
        pos.x *= iResolution.x / iResolution.y;
        pos = pos / zoom + offset;

        vec2 a = vec2(0., 0.);
        vec2 b = pos;

        col += colorize(fractal(a, b, pos));
    #ifdef AALIAS
    }

    return vec4(col / float(AALIAS * AALIAS), 1.);
    #else
    return vec4(col, 1.);
    #endif /* AALIAS */
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    fragColor = aalias(fragCoord);
}

