#define ZOOM_CHANGE 2.
#define ZOOM_MIN .01

#define KEY_ZOOM_IN ivec2(87, 0)
#define KEY_ZOOM_OUT ivec2(83, 0)

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    if (fragCoord.x >= 1. || fragCoord.y >= 1.)
        discard;

    // (pos.x, pos.y, zoom, _)
    vec4 state = texelFetch(iChannel0, ivec2(0, 0), 0);
    if (iFrame == 0)
        state = vec4(0., 0., .5, 0.);

    float dzoom = 1.;
    if (texelFetch(iChannel1, KEY_ZOOM_IN, 0).x > 0.)
        dzoom = pow(ZOOM_CHANGE, iTimeDelta);
    if (texelFetch(iChannel1, KEY_ZOOM_OUT, 0).x > 0.)
        dzoom = pow(1. / ZOOM_CHANGE, iTimeDelta);

    if (dzoom != 1.) {
        vec2 uv = iMouse.xy / iResolution.xy;
        vec2 pos = (uv - vec2(.5, .5)) * 2.;
        pos.x *= iResolution.x / iResolution.y;
        pos = pos / state.z + state.xy;
        state.xy = pos + (state.xy - pos) / dzoom;
        state.z *= dzoom;
    }
    if (state.z < ZOOM_MIN)
        state.z = ZOOM_MIN;

    fragColor = state;
}
